command:
$ErrorActionPreference="Stop"
$repo="C:\dev\flyExplorer"
$main="0b3ba42fe528f31fa4d6978b11d58a8f50a884c1"
$candidate="fc8712fe03eca36c766dfb1b758cde3a160958e9"
$branch="work/verification-infra-simplify-20261005"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "candidate moved"}
& git diff --quiet $main $candidate -- app/winui src/base
if($LASTEXITCODE -eq 1){throw "product changed; accepted Release binary cannot be reused"}
if($LASTEXITCODE -gt 1){throw "product diff check failed"}
$dirty=@(& git status --porcelain)
if($dirty.Count -ne 0){throw ("persistent checkout is dirty: "+($dirty -join "; "))}
& git checkout -B $branch ("refs/remotes/origin/"+$branch)
if($LASTEXITCODE -ne 0){throw "candidate checkout failed"}
if((& git rev-parse HEAD).Trim() -ne $candidate){throw "candidate checkout mismatch"}
$exe=Join-Path $repo "out\winui\Release\flyExplorer.exe"
if(-not(Test-Path -LiteralPath $exe -PathType Leaf)){throw "reusable accepted Release binary missing"}
$hash=(Get-FileHash -Algorithm SHA256 -LiteralPath $exe).Hash
Write-Host ("REUSED_RELEASE_SHA256="+$hash)

& python -X utf8 tools\winui\runner_health.py --configuration Release --require-exe
if($LASTEXITCODE -ne 0){throw "runner health failed"}

& python -X utf8 tools\winui\high_contrast_acceptance.py --configuration Release
if($LASTEXITCODE -ne 0){throw "High Contrast targeted acceptance failed"}

$evidence=Join-Path $repo "logs\remote-evidence"
New-Item -ItemType Directory -Force -Path $evidence | Out-Null
foreach($name in @("candidate-high-contrast-shell.png","candidate-high-contrast-search.png")){
  $source=Join-Path $repo ("logs\high-contrast\"+$name)
  if(-not(Test-Path -LiteralPath $source -PathType Leaf)){throw ("missing High Contrast evidence: "+$name)}
  Copy-Item -LiteralPath $source -Destination (Join-Path $evidence $name) -Force
}
@("MAIN="+$main,"CANDIDATE="+$candidate,"REUSED_RELEASE_SHA256="+$hash) |
  Set-Content -LiteralPath (Join-Path $evidence "verification-infra-high-contrast.txt") -Encoding UTF8
Get-Content -Raw -Encoding UTF8 (Join-Path $evidence "high-contrast-result.json") | Write-Host
& git diff --check $main $candidate
if($LASTEXITCODE -ne 0){throw "candidate diff check failed"}
Write-Host "TARGETED_HIGH_CONTRAST_HARNESS_ACCEPTANCE_PASS"
